import {tagSeasonalInstance} from '../world/seasonal-appearance.js';
import * as THREE from 'three';
import {PRODUCE_FIXTURES,PRODUCE_BY_ID} from './layout.js';
const COLORS={strawberry:'#d95662',tomato:'#df6448',pumpkin:'#e6a04b',leafy:'#82ad62',peach:'#eba9a0',pear:'#d5b967',mandarin:'#eda03f'};
export const LOW_PICK_FLOOR_LIFT=.07183277606964111; // Measured original gatherShell foot underside; no rig change.
export const PICK_HAND=Object.freeze({bed:[.545,.22867446375508346,.5014050804263822],tree:[.545,1.0303836672210214,.5773021851674948],tomato:[.545,1.0303836672210214,.5773021851674948]});
export const harvestPose=node=>node.kind==='tree'||node.species==='tomato'?'pickFruit':'gatherShell';
export function producePickPoint(node){const h=PICK_HAND[node.species==='tomato'?'tomato':node.kind],s=Math.sin(node.approach.yaw),c=Math.cos(node.approach.yaw);return [node.approach.x+h[0]*c+h[2]*s,.05+h[1]-(node.kind==='bed'&&node.species!=='tomato'?LOW_PICK_FLOOR_LIFT:0),node.approach.z-h[0]*s+h[2]*c];}
function leafGeometry(){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute([0,0,-1,-.5,0,0,0,.14,0,.5,0,0,0,0,1],3));g.setIndex([0,1,2,0,2,3,1,4,2,2,4,3]);g.computeVertexNormals();return g;}
export function produceGeometries(){return {round:new THREE.SphereGeometry(1,8,5),lettuce:new THREE.SphereGeometry(1,6,4),berry:new THREE.LatheGeometry([new THREE.Vector2(.005,-1),new THREE.Vector2(.45,-.75),new THREE.Vector2(.82,-.25),new THREE.Vector2(1,.3),new THREE.Vector2(.72,.72),new THREE.Vector2(0,.8)],8),leaf:leafGeometry(),stem:new THREE.CylinderGeometry(.65,1,1,7),box:new THREE.BoxGeometry(1,1,1)};}
/** One bounded instanced pool per shape. Stage changes only update instance transforms. */
export function createProduceView(parent,progress){
 const root=new THREE.Group();root.name='park.produce';parent.add(root);const geometries=produceGeometries(),material=new THREE.MeshStandardMaterial({color:'white',roughness:.9,side:THREE.DoubleSide}),records=[],batches={},nodeStates=new Map(),dummy=new THREE.Object3D(),color=new THREE.Color();let disposed=false,care=null;
 const add=(shape,c,p,s=[1,1,1],rotation=[0,0,0],node=null,stage='always')=>{const r={shape,color:c,p,s,rotation,node,stage};records.push(r);return r;};
 const leaf=(x,y,z,size=.18,yaw=0,c='#70985e',node=null,stage='always')=>add('leaf',c,[x,y,z],[size,size,size],[.18,yaw,0],node,stage);
 function fruit(species,p,size,node,stage='ready'){const [x,y,z]=p,c=COLORS[species];if(species==='strawberry'){add('berry',c,p,[size,size*1.22,size],[],node,stage);for(let i=0;i<4;i++)leaf(x,y+size*.8,z,size*.78,i*Math.PI/2,'#648f52',node,stage);for(let i=0;i<4;i++){const a=i*Math.PI/2;add('round','#ffe7ae',[x+Math.cos(a)*size*.85,y,z+Math.sin(a)*size*.85],[.011,.018,.01],[],node,stage);}}
  else if(species==='pear'){add('round',c,p,[size,size*.96,size],[],node,stage);add('round',c,[x,y+size*.8,z],[size*.57,size*.86,size*.57],[],node,stage);add('stem','#83624a',[x,y+size*1.52,z],[.024,.1,.024],[],node,stage);}
  else if(species==='pumpkin'){for(let i=0;i<5;i++){const a=i*Math.PI*2/5;add('round',i%2?'#d98e3c':c,[x+Math.cos(a)*size*.38,y,z+Math.sin(a)*size*.38],[size*.67,size*.75,size*.67],[],node,stage);}add('stem','#718152',[x,y+size*.85,z],[.045,.12,.045],[0,0,.15],node,stage);}
  else if(species==='leafy'){for(let i=0;i<4;i++){const a=i*2.4;add('lettuce',i%2?'#a4c77f':c,[x+Math.cos(a)*size*.3,y+i*.017,z+Math.sin(a)*size*.3],[size*.74,size*.24,size],[.45,a,0],node,stage);}add('lettuce','#a5c981',[x,y+.06,z],[size*.55,size*.48,size*.55],[],node,stage);}
  else{add('round',c,p,[size,size*(species==='mandarin'?.83:1),size],[],node,stage);if(species==='peach')add('round','#e49a94',[x+size*.4,y,z],[size*.63,size*.91,size*.9],[],node,stage);add('stem','#6e864c',[x,y+size*.93,z],[.025,.06,.025],[],node,stage);leaf(x+size*.45,y+size,z,size*.8,.8,'#5f8b51',node,stage);if(species==='tomato')for(let i=0;i<4;i++)leaf(x,y+size*.95,z,size*.8,i*Math.PI/2,'#648f52',node,stage);}}
 for(const n of PRODUCE_FIXTURES){const id=n.id;nodeStates.set(id,{...n,phase:'seed',ripeCount:0,treeForm:n.kind==='tree'?{species:n.species,trunkHeight:1.7,crownRadius:n.crownRadius}:null});if(n.kind==='bed'){
   add('box','#826e50',[n.x,.08,n.z],[1.4,.11,1.4],[],id);for(const side of [-1,1]){add('box','#bb9d73',[n.x+side*.705,.1,n.z],[.07,.16,1.49]);add('box','#bb9d73',[n.x,.1,n.z+side*.705],[1.49,.16,.07]);}
   for(const [k,[dx,dz]]of [[-.36,-.3],[.31,-.29],[-.34,.3],[.3,.3]].entries()){const x=n.x+dx,z=n.z+dz;for(let j=0;j<4;j++)leaf(x,.17,z,.16,j*Math.PI/2,'#70985e',id);add('round','#f5ebc6',[x,.23,z],[.045,.02,.045],[],id,'seed');if(n.species==='tomato'){add('stem','#668b50',[x,.5,z],[.022,.7,.022],[],id);leaf(x,.56,z,.24,k,'#6e9858',id);fruit(n.species,[x,.73,z],.12,id);}else fruit(n.species,[x,n.species==='pumpkin'?.31:.25,z],n.species==='pumpkin'?.21:n.species==='leafy'?.25:.105,id);}
  }else{
   add('stem','#a5805d',[n.x,.85,n.z],[.21,1.7,.21]);for(const [variant,[dx,dy,dz,s]]of [[0,2.05,0,.67],[-.34,2.14,.02,.46],[.34,2.0,.02,.46]].entries()){const crown=add('round',n.species==='mandarin'?'#78a367':n.species==='pear'?'#91ad6d':'#99bc7e',[n.x+dx,dy,n.z+dz],[s,s*(n.species==='pear'?1.2:1),s]);crown.seasonal={role:n.species==='mandarin'?'canopy.evergreen':'canopy.deciduous',variant};}
   for(let k=0;k<5;k++){const a=k*2.4,p=[n.x+Math.cos(a)*.72,1.60+(k%2)*.34,n.z+Math.sin(a)*.64];fruit(n.species,p,.13,id);add('round','#f1d9bd',p,[.042,.035,.042],[],id,'seed');}
  }
  // A low hanging branch / trailing runner puts one real ripe item at the original hand.
  const tip=producePickPoint(n);fruit(n.species,tip,n.species==='pumpkin'?.18:n.species==='leafy'?.2:.12,id);const middle=[(n.x+tip[0])/2,(tip[1]+(n.kind==='tree'?1.45:.19))/2,(n.z+tip[2])/2],from=new THREE.Vector3(n.x,n.kind==='tree'?1.45:.18,n.z),to=new THREE.Vector3(...tip),delta=to.clone().sub(from),q=new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,1,0),delta.clone().normalize()),e=new THREE.Euler().setFromQuaternion(q);add('stem',n.kind==='tree'?'#a5805d':'#648952',middle,[.023,delta.length(),.023],e.toArray().slice(0,3));
 }
 for(const shape of Object.keys(geometries)){const entries=records.filter(r=>r.shape===shape),mesh=new THREE.InstancedMesh(geometries[shape],material,entries.length);mesh.name='produce.pool.'+shape;mesh.castShadow=true;mesh.receiveShadow=true;mesh.frustumCulled=false;root.add(mesh);entries.forEach((r,i)=>{r.index=i;r.mesh=mesh;mesh.setColorAt(i,color.set(r.color));if(r.seasonal)tagSeasonalInstance(mesh,i,r.seasonal.role,r.seasonal.variant);});batches[shape]=mesh;}
 function redraw(){for(const r of records){const n=r.node&&nodeStates.get(r.node),visible=r.stage==='always'||r.stage===n?.phase;dummy.position.set(...r.p);dummy.rotation.set(r.rotation[0]??0,r.rotation[1]??0,r.rotation[2]??0);const growth=n?.phase==='seed'&&r.shape==='leaf'? .68+(care?.id===r.node?care.amount:0)*.32:1;dummy.scale.set(...(visible?r.s.map(v=>v*growth):[0,0,0]));dummy.updateMatrix();r.mesh.setMatrixAt(r.index,dummy.matrix);}for(const mesh of Object.values(batches))mesh.instanceMatrix.needsUpdate=true;}
 function update(p){for(const n of PRODUCE_FIXTURES){const s=nodeStates.get(n.id);s.phase=p.produce?.nodes[n.id]?.phase??'seed';s.ripeCount=s.phase==='ready'?(n.kind==='tree'?6:5):0;}redraw();}
 update(progress);return {root,update,pickPoint:id=>producePickPoint(PRODUCE_BY_ID[id]),setCare(id,t){const next=id?{id,amount:Math.floor(Math.max(0,Math.min(1,t))*4)/4}:null;if(JSON.stringify(next)===JSON.stringify(care))return;care=next;redraw();},snapshot:()=>({nodes:[...nodeStates.values()].map(n=>({...n})),care}),dispose(){if(disposed)return;disposed=true;root.removeFromParent();Object.values(batches).forEach(m=>m.dispose());Object.values(geometries).forEach(g=>g.dispose());material.dispose();}};
}
